import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  createState,
  frame,
  UP,
  DOWN,
  LEFT,
  RIGHT,
} from './neon.js';

// Mock canvas context
const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  beginPath: () => {},
  fillText: () => {},
};

test('brick bounce: hit top face (bounce DOWN)', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // top-left brick
  brick.alive = true;

  // Position ball just above the brick, moving UP
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - 2, // slightly above
    r: 7,
    vx: 0,
    vy: UP * 100,
  };
  // Force collision (ball.y + ball.r = -2 + 7 = 5, brick.y = 48. Wait, Y grows DOWN)
  // If Y grows DOWN, a ball moving UP has vy < 0.
  // If it hits the top face, it's coming from below or just crossing the top edge.
  // Let's place it so it's overlapping the top edge.
  state.ball.y = brick.y + 2; 
  state.ball.vy = UP * 100; 
  // Now ball.y - ball.r = brick.y + 2 - 7 = brick.y - 5 (overlaps top)
  // Ball is moving UP, hits top of brick, should bounce DOWN.

  // Actually, if ball.vy is UP (-1), it's moving towards the ceiling.
  // If it hits the top of a brick, it must have been BELOW the brick? 
  // No, the bricks are at the top. The ball starts at the bottom and moves UP.
  // So it hits the BOTTOM face of the bricks first.
});

test('brick bounce: hit bottom face (bounce UP)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + 2, 
    r: 7,
    vx: 0,
    vy: UP * 100, // Moving towards ceiling
  };
  // Overlap: ball.y - ball.r = (brick.y + brick.h + 2) - 7 = brick.y + brick.h - 5.
  // Since it's < brick.y + brick.h, it overlaps the bottom.

  frame(mockCtx, state);

  assert.equal(state.ball.vy, Math.abs(state.ball.vy)); // should be DOWN? No, wait.
  // If it hits the bottom, it should bounce DOWN (vy > 0).
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  createState,
  frame,
  UP,
  DOWN,
} from './neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  beginPath: () => {},
  fillText: () => {},
};

test('brick bounce: bottom face (vy flips to DOWN)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball just below brick, moving UP
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + 2, 
    r: 7,
    vx: 0,
    vy: UP * 100,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vy, 100); // Should be DOWN
});

test('brick bounce: top face (vy flips to UP)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball just above brick, moving DOWN
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - 2, 
    r: 7,
    vx: 0,
    vy: DOWN * 100,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vy, -100); // Should be UP
});

test('brick bounce: left face (vx flips to RIGHT)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball to the left of brick, moving RIGHT
  state.ball = {
    x: brick.x - 2, 
    y: brick.y + brick.h / 2,
    r: 7,
    vx: 100,
    vy: 0,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vx, -100); // Should be LEFT
});

test('brick bounce: right face (vx flips to LEFT)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball to the right of brick, moving LEFT
  state.ball = {
    x: brick.x + brick.w + 2, 
    y: brick.y + brick.h / 2,
    r: 7,
    vx: -100,
    vy: 0,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vx, 100); // Should be RIGHT
});

test('brick bounce: corner hit (vx and vy flip)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball hitting bottom-left corner
  state.ball = {
    x: brick.x - 2,
    y: brick.y + brick.h + 2,
    r: 7,
    vx: 100,
    vy: UP * 100,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vx, -100);
  assert.equal(state.ball.vy, 100);
});

