if (collides(state.ball, brick)) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  // Resolution of collision for arcade-style bounce
  const ball = state.ball;

  // Calculate overlap on each axis
  const overlapLeft = (ball.x + ball.r) - brick.x;
  const overlapRight = (brick.x + brick.w) - (ball.x - ball.r);
  const overlapTop = (ball.y + ball.r) - brick.y;
  const overlapBottom = (brick.y + brick.h) - (ball.y - ball.r);

  const minXOverlap = Math.min(overlapLeft, overlapRight);
  const minYOverlap = Math.min(overlapTop, overlapBottom);

  if (minXOverlap < minYOverlap) {
    // Side hit
    if (overlapLeft < overlapRight) {
      ball.vx = Math.abs(ball.vx);
      ball.x = brick.x - ball.r;
    } else {
      ball.vx = -Math.abs(ball.vx);
      ball.x = brick.x + brick.w + ball.r;
    }
  } else if (minYOverlap < minXOverlap) {
    // Top/Bottom hit
    if (overlapTop < overlapBottom) {
      ball.vy = Math.abs(ball.vy);
      ball.y = brick.y - ball.r;
    } else {
      ball.vy = -Math.abs(ball.vy);
      ball.y = brick.y + brick.h + ball.r;
    }
  } else {
    // Corner hit
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    // Push out on both axes to avoid sticking
    if (overlapLeft < overlapRight) ball.x = brick.x - ball.r;
    else ball.x = brick.x + brick.w + ball.r;
    if (overlapTop < overlapBottom) ball.y = brick.y - ball.r;
    else ball.y = brick.y + brick.h + ball.r;
  }
}

