import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  createState,
  frame,
  UP,
  DOWN,
} from './neon.js';

const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fill: () => {},
  beginPath: () => {},
  fillText: () => {},
};

test('brick bounce: bottom face (vy flips to DOWN)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball just below brick, moving UP
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + 2, 
    r: 7,
    vx: 0,
    vy: UP * 100,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vy, 100); // Should be DOWN
});

test('brick bounce: top face (vy flips to UP)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball just above brick, moving DOWN
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - 2, 
    r: 7,
    vx: 0,
    vy: DOWN * 100,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vy, -100); // Should be UP
});

test('brick bounce: left face (vx flips to RIGHT)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball to the left of brick, moving RIGHT
  state.ball = {
    x: brick.x - 2, 
    y: brick.y + brick.h / 2,
    r: 7,
    vx: 100,
    vy: 0,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vx, -100); // Should be LEFT
});

test('brick bounce: right face (vx flips to LEFT)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball to the right of brick, moving LEFT
  state.ball = {
    x: brick.x + brick.w + 2, 
    y: brick.y + brick.h / 2,
    r: 7,
    vx: -100,
    vy: 0,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vx, 100); // Should be RIGHT
});

test('brick bounce: corner hit (vx and vy flip)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball hitting bottom-left corner
  state.ball = {
    x: brick.x - 2,
    y: brick.y + brick.h + 2,
    r: 7,
    vx: 100,
    vy: UP * 100,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vx, -100);
  assert.equal(state.ball.vy, 100);
});

